import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        TokenReader tr = new TokenReader(System.in);
        long n = tr.nextInt();
        long m = tr.nextInt();
        if (n > m) {
            long tmp = n;
            n = m;
            m = tmp;
        }
        long ans;
        if (n == 1) {
            int r = (int) (m % 6);
            ans = m - new long[]{0, 1, 2, 3, 2, 1}[r];
        } else if (n == 2) {
            if (m == 2) ans = 0;
            else if (m == 3) ans = 4;
            else if (m == 7) ans = 12;
            else ans = m * 2;
        } else {
            ans = (n & 1L) == 1 && (m & 1L) == 1 ? n * m - 1 : n * m;
        }
        PrintWriter out = new PrintWriter(System.out);
        out.println(ans);
        out.close();
    }

    static class TokenReader {
        private BufferedReader br;
        private StringTokenizer st;

        public TokenReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() {
            try {
                while (st == null || !st.hasMoreTokens()) {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                }
                return st.nextToken();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
